def registrar(funcao):
    def wrapper(valor):
        print("chamada registrada")
        return funcao(valor)
    return wrapper

@registrar
def dobro(n):
    return n * 2

print(dobro(3))

def defeituoso(funcao):
    def wrapper(*args):
        funcao(*args)
    return wrapper

def corrigido(funcao):
    def wrapper(*args, **kwargs):
        return funcao(*args, **kwargs)
    return wrapper

def somar(a, b=0):
    return a + b

ruim = defeituoso(somar)
print(ruim(2, 3))
try:
    ruim(2, b=3)
except TypeError:
    print("argumento nomeado rejeitado")

bom = corrigido(somar)
print(bom(2, b=3))

from functools import wraps

def contar(funcao):
    @wraps(funcao)
    def wrapper(*args, **kwargs):
        wrapper.chamadas += 1
        return funcao(*args, **kwargs)

    wrapper.chamadas = 0
    return wrapper

@contar
def etiqueta(texto, prefixo="ID"):
    return f"{prefixo}: {texto}"

print(etiqueta.chamadas)
print(etiqueta("a"))
print(etiqueta("b", prefixo="Lote"))
print(etiqueta.__name__, etiqueta.chamadas)

